CREATE TYPE "Provider" AS ENUM ('OPENAI', 'GEMINI', 'ANTHROPIC');
CREATE TYPE "AccountStatus" AS ENUM ('ACTIVE', 'EXPIRED', 'REVOKED');
CREATE TYPE "SessionRole" AS ENUM ('ADMIN', 'TEMPORARY_USER');
CREATE TYPE "MessageRole" AS ENUM ('USER', 'ASSISTANT', 'SYSTEM');
CREATE TYPE "AuditAction" AS ENUM ('LOGIN', 'LOGOUT', 'CREATE_USER', 'REVOKE_USER', 'UPDATE_LIMITS', 'CHAT', 'DENIED_CHAT');
CREATE TABLE "Administrator" ("id" UUID PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "TemporaryUser" ("id" UUID PRIMARY KEY, "username" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "status" "AccountStatus" NOT NULL DEFAULT 'ACTIVE', "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "promptLimit" INTEGER NOT NULL DEFAULT 50, "promptCount" INTEGER NOT NULL DEFAULT 0, "tokenBudget" INTEGER NOT NULL DEFAULT 100000, "tokenUsed" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdById" UUID NOT NULL REFERENCES "Administrator"("id") ON DELETE RESTRICT);
CREATE TABLE "Session" ("id" UUID PRIMARY KEY, "tokenHash" TEXT NOT NULL UNIQUE, "role" "SessionRole" NOT NULL, "administratorId" UUID REFERENCES "Administrator"("id") ON DELETE CASCADE, "temporaryUserId" UUID REFERENCES "TemporaryUser"("id") ON DELETE CASCADE, "csrfToken" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "session_one_owner" CHECK (("administratorId" IS NOT NULL)::int + ("temporaryUserId" IS NOT NULL)::int = 1));
CREATE TABLE "Conversation" ("id" UUID PRIMARY KEY, "temporaryUserId" UUID NOT NULL REFERENCES "TemporaryUser"("id") ON DELETE CASCADE, "title" TEXT NOT NULL DEFAULT 'New conversation', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Message" ("id" UUID PRIMARY KEY, "conversationId" UUID NOT NULL REFERENCES "Conversation"("id") ON DELETE CASCADE, "role" "MessageRole" NOT NULL, "content" TEXT NOT NULL, "provider" "Provider", "model" TEXT, "inputTokens" INTEGER NOT NULL DEFAULT 0, "outputTokens" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "UsageLog" ("id" UUID PRIMARY KEY, "temporaryUserId" UUID NOT NULL REFERENCES "TemporaryUser"("id") ON DELETE CASCADE, "provider" "Provider" NOT NULL, "model" TEXT NOT NULL, "inputTokens" INTEGER NOT NULL DEFAULT 0, "outputTokens" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditEvent" ("id" UUID PRIMARY KEY, "action" "AuditAction" NOT NULL, "ip" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "administratorId" UUID REFERENCES "Administrator"("id") ON DELETE SET NULL, "temporaryUserId" UUID REFERENCES "TemporaryUser"("id") ON DELETE SET NULL);
CREATE INDEX "TemporaryUser_status_expiresAt_idx" ON "TemporaryUser"("status", "expiresAt"); CREATE INDEX "Session_temporaryUserId_expiresAt_idx" ON "Session"("temporaryUserId", "expiresAt"); CREATE INDEX "Conversation_temporaryUserId_updatedAt_idx" ON "Conversation"("temporaryUserId", "updatedAt"); CREATE INDEX "Message_conversationId_createdAt_idx" ON "Message"("conversationId", "createdAt"); CREATE INDEX "UsageLog_temporaryUserId_createdAt_idx" ON "UsageLog"("temporaryUserId", "createdAt");
